<script setup>
import {ref,computed,watch} from 'vue';
import {useRoute} from 'vue-router';
import {modelApi} from '@/services/models.js';
import {teachingApi} from '@/services/teaching.js';
const props=defineProps({open:Boolean,report:Object,knowledge:Object});const emit=defineEmits(['update:open','saved']);const route=useRoute();
const taskId=ref(''),knowledgeId=ref(''),kind=ref('learning'),scope=ref('all'),ids=ref([]),targetTask=ref(''),targetKind=ref('learn'),content=ref(''),due=ref(''),caseId=ref(''),caseReference=ref(null),preview=ref(false),busy=ref(false),error=ref(''),key=ref(''),wrongIds=ref({});
const labels={learning:'补充讲解',correction:'错题订正',foundation:'前置知识复习',retest:'独立复测',note:'教师补充说明'};
const candidates=computed(()=>{const k=props.report?.knowledge.find(k=>k.id===knowledgeId.value);const allowed=scope.value==='difficulty'?new Set(k?.students.filter(s=>s.error).map(s=>s.id)||[]):null;return (props.report?.students||[]).filter(s=>s.records.some(r=>r.taskId===taskId.value)&&(!allowed||allowed.has(s.id)))});
const recipients=computed(()=>scope.value==='all'?candidates.value:candidates.value.filter(s=>ids.value.includes(s.id)));
function reset(){taskId.value=props.report?.tasks[0]?.id||'';targetTask.value=taskId.value;knowledgeId.value=props.knowledge?.id||props.report?.knowledge[0]?.id||'';scope.value=props.knowledge?'difficulty':'all';ids.value=[];content.value='';due.value='';caseId.value=String(route.query.interventionCase||'');key.value=crypto.randomUUID();preview.value=false;error.value='';wrongIds.value={};}
watch(()=>props.open,async v=>{if(v){reset();caseReference.value=null;if(caseId.value){const id=caseId.value;try{const value=await modelApi.caseDetail(id);if(props.open&&caseId.value===id)caseReference.value=value}catch(e){if(props.open&&caseId.value===id)error.value=e.message}}}});watch([taskId,scope,knowledgeId],()=>{ids.value=[];preview.value=false});
function wrongs(s){return s.evidence.filter(e=>e.sourceType==='wrong'&&e.taskId===taskId.value)}
async function send(){if(busy.value)return;busy.value=true;error.value='';try{const targets={};if(kind.value==='correction')for(const s of recipients.value){if(!wrongIds.value[s.id])throw new Error('请为每名学生选择原错题。');targets[s.id]={wrongId:wrongIds.value[s.id]};}await teachingApi.arrange(taskId.value,{requestKey:key.value,kind:kind.value,knowledgeId:knowledgeId.value,difficultyOnly:scope.value==='difficulty',studentIds:recipients.value.map(s=>s.id),content:content.value,dueDate:due.value,target:{taskId:targetTask.value,kind:kind.value==='retest'?'check':targetKind.value},targets,caseId:caseId.value||undefined});emit('update:open',false);emit('saved')}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><AppDialog :open="open" @update:open="emit('update:open',$event)" title="安排补充教学" content-class="student-detail-dialog"><form class="intervention-form" @submit.prevent="preview?send():preview=true">
<template v-if="!preview"><div class="analytics-form-grid"><label class="field-label">来源任务<AppSelect v-model="taskId" label="来源任务" :options="report.tasks.map(t=>({value:t.id,label:t.title}))"/></label><label class="field-label">知识点<AppSelect v-model="knowledgeId" label="干预知识点" :options="report.knowledge.map(k=>({value:k.id,label:k.name}))"/></label><label class="field-label">安排类型<AppSelect v-model="kind" label="教学安排类型" :options="Object.entries(labels).map(([value,label])=>({value,label}))"/></label><label class="field-label">接收范围<AppSelect v-model="scope" label="教学接收范围" :options="[{value:'all',label:'本任务全部在班学生'},{value:'selected',label:'指定学生'},{value:'difficulty',label:'有独立错误证据的学生'}]"/></label></div>
<div class="intervention-students"><div v-for="s in candidates" :key="s.id"><AppCheckbox v-if="scope!=='all'" v-model="ids" :value="s.id">{{s.name}}</AppCheckbox><span v-else>{{s.name}}</span><Status v-if="scope==='difficulty'">有原始错误</Status></div><p v-if="!candidates.length">没有符合当前条件的学生</p></div>
<template v-if="kind==='correction'"><label v-for="s in recipients" :key="s.id" class="field-label">{{s.name}}的原错题<AppSelect v-model="wrongIds[s.id]" :label="s.name+'的原错题'" :options="wrongs(s).map(e=>({value:e.wrongId,label:e.equation||e.prompt}))"/></label></template>
<details v-else class="ops-disclosure"><summary>学习入口</summary><div class="analytics-form-grid"><label class="field-label">学习课时<AppSelect v-model="targetTask" label="目标课时" :options="report.tasks.map(t=>({value:t.id,label:t.title}))"/></label><label v-if="kind!=='retest'" class="field-label">进入页面<AppSelect v-model="targetKind" label="目标页面" :options="[{value:'learn',label:'讲解与活动'},{value:'check',label:'独立检查'}]"/></label></div></details>
<label class="field-label">教师安排<Textarea v-model="content" required/></label><div class="analytics-form-grid"><label class="field-label">截止日期<Input v-model="due" type="date"/></label><div v-if="caseId"><span class="field-label">参考案例</span><p>{{caseReference?.title||'正在读取案例…'}}</p><AppButton type="button" variant="ghost" @click="caseId=''">移除参考</AppButton></div></div></template>
<template v-else><h3>{{labels[kind]}} 　 {{recipients.length}} 人</h3><p>{{report.knowledge.find(k=>k.id===knowledgeId)?.name}}</p><p>{{recipients.map(s=>s.name).join('、')}}</p><p class="preserve-lines">{{content}}</p><p>发布后学生将收到安排；已有作答、原任务和历史核验保留。</p><AppButton variant="outline" @click="preview=false" type="button">返回编辑</AppButton></template>
<AppAlert type="error" v-if="error" class="form-error" role="alert">{{error}}</AppAlert><AppButton type="submit" :disabled="busy||!content.trim()||!recipients.length||!knowledgeId">{{busy?'发布中…':preview?'确认发布':'预览接收名单'}}</AppButton>
</form></AppDialog></template>
